import itertools
from pysat.solvers import Glucose3

N = 16
def get_var(r, c, num):
    return r * N * N + c * N + (num - 1) + 1

solver = Glucose3()

# Each cell exactly one number
for r in range(N):
    for c in range(N):
        clause = [get_var(r, c, num) for num in range(1, N+1)]
        solver.add_clause(clause)
        for num1, num2 in itertools.combinations(range(1, N+1), 2):
            solver.add_clause([-get_var(r, c, num1), -get_var(r, c, num2)])

# Each row each num exactly once
for r in range(N):
    for num in range(1, N+1):
        clause = [get_var(r, c, num) for c in range(N)]
        solver.add_clause(clause)
        for c1, c2 in itertools.combinations(range(N), 2):
            solver.add_clause([-get_var(r, c1, num), -get_var(r, c2, num)])

# Each col each num exactly once
for c in range(N):
    for num in range(1, N+1):
        clause = [get_var(r, c, num) for r in range(N)]
        solver.add_clause(clause)
        for r1, r2 in itertools.combinations(range(N), 2):
            solver.add_clause([-get_var(r1, c, num), -get_var(r2, c, num)])

# Each block each num exactly once
for br in range(4):
    for bc in range(4):
        for num in range(1, N+1):
            positions = [(br*4 + i, bc*4 + j) for i in range(4) for j in range(4)]
            clause = [get_var(r, c, num) for r, c in positions]
            solver.add_clause(clause)
            for (r1,c1), (r2,c2) in itertools.combinations(positions, 2):
                solver.add_clause([-get_var(r1, c1, num), -get_var(r2, c2, num)])

assignments = {
5:6,13:14,14:15,18:7,22:3,26:15,27:16,33:10,34:11,42:3,53:10,54:11,57:6,58:7,69:5,71:7,80:6,81:5,83:7,84:2,85:1,94:12,103:15,106:4,107:3,109:5,112:14,115:15,120:6,135:6,136:11,140:15,141:16,148:3,150:1,170:1,175:6,185:8,188:3,190:1,196:8,199:5,201:11,203:9,208:8,218:14,240:16,241:15,243:13,244:12,253:3
}

for idx, val in assignments.items():
    r = idx // N
    c = idx % N
    solver.add_clause([get_var(r, c, val)])

if solver.solve():
    model = solver.get_model()
    model_set = set(model)
    solution = [0] * (N * N)
    for r in range(N):
        for c in range(N):
            for num in range(1, N+1):
                v = get_var(r, c, num)
                if v in model_set:
                    solution[r*N + c] = num
                    break
    print(solution)
else:
    print("UNSATISFIABLE")
